export function sleepPhaseMemoryReconsolidation(memoryStore) {
  const STDPAdjustments = (synapses) => {
    synapses.forEach(synapse => {
      if (synapse.activityLevel > 0.8) {
        synapse.strength += 0.1;
      } else if (synapse.activityLevel < 0.3) {
        synapse.strength -= 0.1;
      }
    });
    return synapses;
  };

  const consolidateMemory = (memoryStore) => {
    const keyMemories = memoryStore.filter(memory => memory.relevanceScore > 0.7);
    const irrelevantMemories = memoryStore.filter(memory => memory.relevanceScore <= 0.7);

    keyMemories.forEach(memory => {
      memory.stability += 0.2;
    });

    irrelevantMemories.forEach(memory => {
      memory.stability -= 0.2;
    });

    return [...keyMemories, ...irrelevantMemories];
  };

  const updatedSynapses = STDPAdjustments(memoryStore.synapses);
  const updatedMemories = consolidateMemory(memoryStore.memories);

  return {
    synapses: updatedSynapses,
    memories: updatedMemories
  };
}